//! Macro expansion for IREE compiled model.
//!
//! Implement [`oneliner_runtime::ModelInference`] for the wrapped struct.
//! Glue the trait with the model ops dispatch code in rust generated by `oneliner-macro/python/iree_stream_flow_to_rust.py`.

use proc_macro2::Span;
use proc_macro2::TokenStream;
use quote::{format_ident, quote};
use syn::{ItemStruct, LitStr, Meta, NestedMeta};

use super::IreeArtifacts;
use crate::utils::{path_lit, rust_ident};

/// Expand the model struct and implement [`oneliner_runtime::ModelInference`].
pub(super) fn expand(input_struct: ItemStruct, artifacts: IreeArtifacts) -> TokenStream {
    let struct_ident = &input_struct.ident;
    let struct_vis = &input_struct.vis;
    let struct_attrs = &input_struct.attrs;
    let module_ident = format_ident!("__oneliner_iree_{}", rust_ident(&struct_ident.to_string()));
    let infer_ident = format_ident!(
        "__oneliner_iree_infer_{}",
        rust_ident(&struct_ident.to_string())
    );
    let paths = &artifacts.paths;
    let flow_rs = path_lit(&paths.flow_rs);
    let model_path = path_lit(&paths.model);
    let object_path = path_lit(&paths.object);
    let input_size = artifacts.input.size;
    let output_size = artifacts.output.size;
    let params_size = artifacts.params_size;
    let code_size = artifacts.code_size;
    let rodata_size = artifacts.rodata_size;
    let total_flash_size = params_size + code_size + rodata_size;
    let workspace_size = artifacts.workspace_size;
    let execute_fns = &artifacts.execute_fns;
    let query_fn = &artifacts.query_fn;
    let query_link_name = LitStr::new(&artifacts.query_link_name, Span::call_site());
    let input_type = artifacts.input_tensor.element_type.rust_tokens();
    let output_type = artifacts.output_tensor.element_type.rust_tokens();
    let [input_d0, input_d1, input_d2, input_d3] = artifacts.input_tensor.shape;
    let [output_d0, output_d1, output_d2, output_d3] = artifacts.output_tensor.shape;

    let input_tensor = quote! {
        ::oneliner::runtime::Tensor<
            #input_type,
            #input_d0,
            #input_d1,
            #input_d2,
            #input_d3,
        >
    };
    let output_tensor = quote! {
        ::oneliner::runtime::Tensor<
            #output_type,
            #output_d0,
            #output_d1,
            #output_d2,
            #output_d3,
        >
    };
    let workspace_type = quote! { #module_ident::Workspace };

    let execute = quote! {
        #(
            #module_ident::#execute_fns(
                workspace,
                input_buffer,
                output_buffer,
            )
                .expect("Oneliner inference dispatch failed");
        )*
    };

    // Shared by the owned model and the borrowed handle. Keeping one copy keeps
    // buffer setup, dispatch and owned-output construction identical.
    let infer_fn = quote! {
        #[allow(dead_code)]
        fn #infer_ident(
            workspace: &mut #workspace_type,
            input: &#input_tensor,
        ) -> #output_tensor {
            let input_buffer = ::oneliner::runtime::Buffer::new(
                input.as_ptr().cast::<u8>(),
                input.byte_len(),
            );

            let mut output = <#output_tensor>::new(0 as #output_type);
            let output_buffer = ::oneliner::runtime::BufferMut::new(
                output.as_mut_ptr().cast::<u8>(),
                output.byte_len(),
            );

            #execute

            output
        }
    };

    let model_definition = quote! {
        #(#struct_attrs)*
        #struct_vis struct #struct_ident {
            workspace: #workspace_type,
        }
    };

    let model_constructor = quote! {
        impl #struct_ident {
            /// Creates a model with its own inline workspace.
            pub const fn new() -> Self {
                Self {
                    workspace: #workspace_type::new(),
                }
            }
        }
    };

    let default_impl = quote! {
        impl Default for #struct_ident {
            fn default() -> Self {
                Self::new()
            }
        }
    };


    quote! {
        #infer_fn

        #model_definition

        #[allow(improper_ctypes, non_camel_case_types, non_snake_case, non_upper_case_globals)]
        #[link(name = #object_path, kind = "static", modifiers = "+verbatim")]
        unsafe extern "C" {}

        #[allow(
            dead_code,
            improper_ctypes,
            mutable_transmutes,
            non_camel_case_types,
            non_snake_case,
            non_upper_case_globals,
            unused_imports,
            unused_macros,
            unused_mut,
            unused_variables
        )]
        mod #module_ident {
            use ::oneliner::runtime::{
                concurrent, dispatch_fn_from_library, fill, try_dispatch, Access, Aligned,
                AlignedType, AnyBufferRange, Buffer, BufferMut, BufferSource, Error,
                iree_hal_executable_environment_v0_t, iree_hal_executable_library_header_t,
                iree_hal_executable_library_query_fn_t,
            };

            unsafe extern "C" {
                #[link_name = #query_link_name]
                pub unsafe fn #query_fn(
                    max_version: u32,
                    environment: *const iree_hal_executable_environment_v0_t,
                ) -> *const *const iree_hal_executable_library_header_t;
            }

            static QUERY_FN_PTR: iree_hal_executable_library_query_fn_t = #query_fn;

            include!(#flow_rs);
        }

        #model_constructor
        #default_impl

        impl #struct_ident {
            /// Model backend and original source path on the build host.
            pub const METADATA: ::oneliner::runtime::ModelMetadata = ::oneliner::runtime::ModelMetadata {
                backend: "iree",
                model_path: #model_path,
            };

            /// Tensor byte counts and model-only footprint estimates.
            pub const RESOURCE_USAGE: ::oneliner::runtime::ResourceUsage = ::oneliner::runtime::ResourceUsage {
                io: ::oneliner::runtime::IOSize {
                    input_size: #input_size,
                    output_size: #output_size,
                },
                ram: ::oneliner::runtime::RAMUsage {
                    workspace_size: #workspace_size,
                },
                flash: ::oneliner::runtime::FlashUsage {
                    params_size: #params_size,
                    code_size: #code_size,
                    rodata_size: #rodata_size,
                    total_flash_size: #total_flash_size,
                },
            };
        }

        impl ::oneliner::runtime::ModelInference for #struct_ident {
            type InputTensor = #input_tensor;
            type OutputTensor = #output_tensor;

            /// Creates an input tensor filled with numeric zeros.
            ///
            /// Apply the model's required preprocessing and quantization before
            /// inference; numeric zero need not represent a quantized real zero.
            fn create_input_tensor() -> Self::InputTensor {
                Self::InputTensor::new(0 as #input_type)
            }

            /// Runs all generated command blocks and returns an owned output.
            ///
            /// # Panics
            ///
            /// Panics on dispatch failure.
            fn run(&mut self, input: &Self::InputTensor) -> Self::OutputTensor {
                #infer_ident(&mut self.workspace, input)
            }
        }
    }
}